css:
.fx-bsf{display:grid;gap:1.4em;justify-items:center;text-align:center}
.fx-bsf h2{font-size:2.3em}.fx-bsf p{opacity:.6}
.fx-bsf .row{display:flex;gap:1em;flex-wrap:wrap;justify-content:center}
.fx-bsf .b{position:relative;overflow:hidden;isolation:isolate;display:inline-flex;align-items:center;gap:.6em;padding:.95em 1.7em;border-radius:var(--radius);font:700 .95em var(--font-body);text-decoration:none;border:1.5px solid var(--primary);color:var(--primary);transition:color calc(.35s/var(--speed)) ease}
.fx-bsf .b::before{content:"";position:absolute;inset:0;z-index:-1;background:var(--primary);transform:translateX(-101%);transition:transform calc(.45s/var(--speed)) cubic-bezier(.7,0,.2,1)}
.fx-bsf .b:hover{color:var(--on-primary)}.fx-bsf .b:hover::before{transform:none}
.fx-bsf .solid{background:var(--primary);color:var(--on-primary)}.fx-bsf .solid::before{background:var(--accent)}
.fx-bsf .solid:hover{color:var(--on-accent);border-color:var(--accent)}
.fx-bsf .pill{border-radius:999px;border-color:var(--accent);color:var(--accent)}.fx-bsf .pill::before{background:var(--accent)}.fx-bsf .pill:hover{color:var(--on-accent)}
.fx-bsf .b i{font-style:normal;transition:transform calc(.35s/var(--speed))}.fx-bsf .b:hover i{transform:translateX(4px)}
@media(prefers-reduced-motion:reduce){.fx-bsf .b,.fx-bsf .b::before,.fx-bsf .b i{transition:none}}
/* touch: :hover mirrored as .is-tap */
.fx-bsf .b.is-tap{color:var(--on-primary)}
.fx-bsf .b.is-tap::before{transform:none}
.fx-bsf .solid.is-tap{color:var(--on-accent);border-color:var(--accent)}
.fx-bsf .pill.is-tap{color:var(--on-accent)}
.fx-bsf .b.is-tap i{transform:translateX(4px)}
